(function(){
'use strict';
let handle=null,stamp=null,running=false;
const canLink=typeof window.showOpenFilePicker==='function'&&!!window.indexedDB;
const database=()=>new Promise((resolve,reject)=>{const req=indexedDB.open('forma-garmin-link',1);req.onupgradeneeded=()=>req.result.createObjectStore('handles');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
async function fileLink(op,val){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('handles',op==='read'?'readonly':'readwrite'),t=tx.objectStore('handles');const q=op==='read'?t.get('source'):op==='delete'?t.delete('source'):t.put(val,'source');tx.oncomplete=()=>{db.close();resolve(q.result)};tx.onabort=tx.onerror=()=>{db.close();reject(tx.error||Error('Could not save file access.'))}})}
async function parseFile(file){if(file.size>32*1024*1024)throw Error('Choose a file smaller than 32 MB.');const parsed=JSON.parse(await file.text());if(!Array.isArray(parsed.records))throw Error('Choose the forma-garmin.json file created by the helper.');const p=window.formaWearParser,rows=p.merge(p.fromText(file.name,JSON.stringify(parsed.records)));if(!rows.length)throw Error('No supported daily readings found.');return rows}
async function refresh(user){if(!handle||running)return 0;running=true;try{const granted=user?await handle.requestPermission({mode:'read'}):await handle.queryPermission({mode:'read'});if(granted!=='granted')throw Error('File access needs permission. Choose Refresh now to grant access.');const f=await handle.getFile(),v=f.lastModified+'-'+f.size;if(v===stamp)return 0;const rows=await parseFile(f);window.formaSaveWear(rows,'Garmin Personal API',!user);stamp=v;return rows.length}finally{running=false}}
window.openGarminSync=()=>{
 const el=document.createElement('dialog');if(document.getElementById('sync-dialog'))return;el.id='sync-dialog';el.className='sync-dialog';el.setAttribute('aria-labelledby','sync-title');el.innerHTML=`<div class="detail-top"><span class="outline-icon">${icon('watch')}</span><h2 id="sync-title">Sync with Garmin</h2><button class="close" aria-label="Close Garmin setup">${icon('close',17)}</button></div><p class="sub">Keep your personal key on your computer. Forma reads a local file of daily measurements from Garmin’s Personal API.</p><ol class="sync-steps"><li><b>Create a personal key in Garmin Connect.</b><p><a href="https://developer.garmin.com/gc-developer-program/personal/personal-api/" rel="noopener noreferrer" target="_blank">Garmin key setup instructions</a></p></li><li><b>Run the sync helper with Python 3.</b><p>Download the helper, open a terminal in the download folder and run the command below. Enter the key at the hidden prompt.</p><a href="forma-garmin-sync.py" download="forma-garmin-sync.py">Download Garmin sync helper</a><pre>python3 forma-garmin-sync.py --watch</pre><p>Leave it running to refresh hourly. Omit <code>--watch</code> for a single update.</p></li><li><b>${canLink?'Link the resulting file.':'Import the resulting file.'}</b><p>${canLink?'Select forma-garmin.json. Forma refreshes your personal workspace while it is open and has permission to read the file.':'Select forma-garmin.json in the wearable import screen after each update.'}</p></li></ol><p role="status" id="sync-feedback" class="note"></p><div class="detail-actions"><button class="btn" id="sync-choose"></button><button class="soft" id="sync-refresh">Refresh now</button><button class="linkbtn" id="sync-forget">Unlink file</button><button class="linkbtn" id="sync-import">Import file once</button></div>`;
 document.body.append(el);const q=s=>el.querySelector(s),msg=s=>q('#sync-feedback').textContent=s;
 const paint=()=>{q('#sync-refresh').hidden=q('#sync-forget').hidden=!handle;q('#sync-choose').hidden=!canLink;q('#sync-choose').textContent=handle?'Choose another file':'Link Garmin file';msg(handle?'Linked file: '+handle.name:'No file linked on this device.')};
 el.onclose=()=>el.remove();q('.close').onclick=()=>el.close();q('#sync-import').onclick=()=>{el.close();window.openWearImport()};
 q('#sync-choose').onclick=async()=>{try{const [pick]=await window.showOpenFilePicker({multiple:false,types:[{description:'Garmin sync JSON',accept:{'application/json':['.json']}}]});const f=await pick.getFile(),rows=await parseFile(f);window.formaSaveWear(rows,'Garmin Personal API');await fileLink('save',pick);handle=pick;stamp=f.lastModified+'-'+f.size;paint();msg('Linked '+f.name+' · '+rows.length+' days read.')}catch(e){if(e.name!=='AbortError')msg(e.name==='SecurityError'?'This browser cannot link a file here. Choose Import file once to load it.':e.message)}};
 q('#sync-refresh').onclick=async()=>{try{const n=await refresh(true);msg(n?n+' days refreshed.':'Your workspace is up to date.')}catch(e){msg(e.message)}};
 q('#sync-forget').onclick=async()=>{try{await fileLink('delete');handle=null;stamp=null;paint();msg('File unlinked. Previously imported readings remain available.')}catch{msg('Unable to unlink this file. Please retry.')}};
 el.showModal();paint();
};
if(canLink){const auto=()=>{if(!document.hidden&&window.formaPersonalActive?.())refresh(false).catch(()=>{})};fileLink('read').then(saved=>{handle=saved||null;auto()}).catch(()=>{});window.addEventListener('focus',auto);document.addEventListener('visibilitychange',auto);setInterval(auto,60000)}
})();
